const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function previewPaths(site){return [['/','Naslovnica'],['/apartmani/','Svi apartmani'],...(site.apartments||[]).filter(a=>a.published!==false).map(a=>['/apartmani/'+a.slug+'/',a.name]),['/o-nama/','O nama'],['/galerija/','Galerija'],['/vodic/','Vodič'],['/kako-do-nas/','Kako do nas'],['/faq/','Česta pitanja'],['/kontakt/','Kontakt']]}
export function showDraftPreview(data){
 const token=crypto.randomUUID(),paths=previewPaths(data),dialog=document.createElement('dialog');dialog.className='editor-site-preview';dialog.setAttribute('aria-label','Privatni pregled nacrta');
 dialog.innerHTML=`<div class="editor-preview-toolbar"><strong>Privatni pregled nacrta</strong><button type="button" class="btn outline" data-preview-close>Zatvori pregled ×</button><label>Stranica<select data-preview-path>${paths.map(([path,label])=>`<option value="${esc(path)}">${esc(label)}</option>`).join('')}</select></label><label>Uređaj<select data-preview-width><option value="390">Mobitel · 390 px</option><option value="768">Tablet · 768 px</option><option value="1440" selected>Računalo · 1440 px</option></select></label><label>Jezik<select data-preview-lang>${['hr','en','de','cs'].map(l=>`<option>${l}</option>`).join('')}</select></label><label>Font<select data-preview-font><option value="100">100 %</option><option value="115">115 %</option><option value="130">130 %</option><option value="150">150 %</option></select></label><p>Stvarna širina prikaza; na manjem zaslonu pomaknite pregled vodoravno. Ovaj prikaz ne objavljuje promjene i ne šalje upite.</p></div><div class="editor-preview-scroll"><iframe title="Prikaz nacrta web stranice" referrerpolicy="no-referrer"></iframe></div>`;
 document.body.append(dialog);const frame=dialog.querySelector('iframe'),field=name=>dialog.querySelector('[data-preview-'+name+']');let closed=false;
 const send=()=>frame.contentWindow?.postMessage({type:'cms-preview-data',token,data,font:field('font').value},location.origin);
 const load=()=>{const url=new URL(field('path').value,location.origin);url.searchParams.set('cms-preview',token);url.searchParams.set('lang',field('lang').value);frame.src=url.href};
 const receive=event=>{if(event.origin===location.origin&&event.source===frame.contentWindow&&event.data?.type==='cms-preview-ready'&&event.data.token===token)send()};window.addEventListener('message',receive);
 const close=()=>{if(closed)return;closed=true;window.removeEventListener('message',receive);dialog.close();dialog.remove()};field('close').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close()});field('path').onchange=load;field('lang').onchange=load;field('font').onchange=send;field('width').onchange=()=>{frame.style.width=field('width').value+'px'};frame.style.width='1440px';dialog.showModal();load();return close;
}
// The parent transfers only the validated public catalogue, never tokens or guests.
export function installDraftPreview({site,validate,render,applyFont}){
 const token=new URL(location.href).searchParams.get('cms-preview');if(!token||window.parent===window)return false;
 window.MELEH_PREVIEW=true;document.querySelector('#app').textContent='Načitavam privatni pregled nacrta…';
 const allowed=()=>new Set(previewPaths(site).map(([path])=>path.replace(/\/$/,'')||'/'));
 window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==window.parent||event.data?.type!=='cms-preview-data'||event.data.token!==token)return;try{Object.assign(site,validate(event.data.data,{allowDataImages:true,allowEmptyCatalogue:true}));applyFont(['100','115','130','150'].includes(event.data.font)?event.data.font:'100');render();let banner=document.querySelector('#cms-private-preview');if(!banner){banner=document.createElement('div');banner.id='cms-private-preview';banner.setAttribute('role','status');document.body.prepend(banner)}banner.textContent='Privatni pregled nacrta · Promjene nisu objavljene · Slanje upita je isključeno.'}catch{document.querySelector('#app').textContent='Nacrt nije spreman za pregled. Vratite se u administraciju i provjerite sadržaj.'}});
 document.addEventListener('submit',event=>{if(event.target.id==='inquiry'){event.preventDefault();event.stopImmediatePropagation();document.querySelector('#cms-private-preview').textContent='Ovo je privatni pregled. Upit nije poslan.'}},true);
 document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link)return;if(link.origin!==location.origin||!allowed().has(link.pathname.replace(/\/$/,'')||'/')||link.target||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey){event.preventDefault();event.stopImmediatePropagation();return}const next=new URL(link.href);next.searchParams.set('cms-preview',token);link.href=next.href},true);
 window.parent.postMessage({type:'cms-preview-ready',token},location.origin);return true;
}
